/// The build-time-compiled tweak corpus (`tweaks/*.yaml`, spec §11). Auto-generated by
/// `build.rs` — do not edit manually. `tweaks::compiled_corpus()` is the accessor.
mod generated_corpus {
    include!(concat!(env!("OUT_DIR"), "/generated_corpus.rs"));
}

pub use debug::{emit_debug_log, is_debug_enabled, set_debug_enabled, DebugLevel, DebugLogEntry};
